next_id=max_id+1
for tpl in new_words:
    nid=str(next_id)
    row={
        'id':nid,
        'word':tpl[1],
        'part_of_speech':tpl[2],
        'cefr_level':tpl[3],
        'definition':tpl[4],
        'example_sentence':tpl[5],
        'notification_line_1':tpl[6],
        'notification_line_2':tpl[7],
        'example_source':tpl[8],
        'context_scenario':tpl[9],
        'context_source':tpl[10],
        'story_text':tpl[11],
        'story_source':tpl[12],
        'context_enabled':'1'
    }
    reader.append(row)
    next_id+=1

# write back
fieldnames=['id','word','part_of_speech','cefr_level','definition','example_sentence','notification_line_1','notification_line_2','example_source','context_scenario','context_source','story_text','story_source','context_enabled']
